export type ExportResponse = ExportResponses[keyof ExportResponses];

export type ChatData = {
    body?: never;
    path?: never;
    query?: never;
    url: '/api/chat';
};

export type ChatResponses = {
    /**
     * Successful Response
     */
    200: unknown;
};
